import unittest
from delivery import retry_delivery

class DeliveryTests(unittest.TestCase):
    def test_contract(self):
        for remote, expected, count in [("applied", "applied", 0), ("absent", "sent", 1), ("unknown", "pending", 0)]:
            with self.subTest(remote=remote):
                calls = []
                def lookup(op):
                    calls.append(("lookup", op))
                    return remote
                def send(op):
                    calls.append(("send", op))
                    return "sent"
                self.assertEqual(retry_delivery(send, lookup, "op-7"), expected)
                self.assertEqual(calls, [("lookup", "op-7")] + [("send", "op-7")] * count)

